    candidates = []
    for ph in range(1, h + 1):
        for pw in range(1, w + 1):
            tile = {}
            ok = True
            for r, c, v in pts:
                k = (r % ph, c % pw)
                if k in tile and tile[k] != v:
                    ok = False
                    break
                tile[k] = v
            if ok:
                candidates.append((ph * pw, ph + pw, ph, pw, tile))
    _, _, ph, pw, tile = min(candidates)

