def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    # Determine the orientation of the repeated stripes: horizontal or diagonal.
    # For each candidate orientation, find the smallest period that agrees with
    # all observed colored cells.
    def pattern(axis):
        vals = {}
        for r, c, v in points:
            k = r if axis == 0 else (c - r) % w
            if k in vals and vals[k] != v:
                return None
            vals[k] = v
        n = h if axis == 0 else w
        for p in range(1, n + 1):
            consistent = True
            base = {}
            for k, v in vals.items():
                q = k % p
                if q in base and base[q] != v:
                    consistent = False
                    break
                base[q] = v
            if consistent:
                return p, base
        return n, vals

    # Horizontal stripes for row-wise examples; diagonals for diagonal guides.
    horiz = pattern(0)
    diag = pattern(1)
    is_diag = False
    # Prefer the direction in which the clues form fewer distinct stripes.
    if len({(c-r) % w for r,c,v in points}) < len({r for r,c,v in points}):
        is_diag = True

    p, base = diag if is_diag else horiz
    if is_diag:
        # Fill remaining residues with the nearest known stripe color.
        keys = list(base)
        if not keys:
            return [row[:] for row in grid]
        def color(k):
            q = k % p
            if q in base:
                return base[q]
            return base[min(keys, key=lambda x: min((q-x)%p, (x-q)%p))]
        return [[color((c-r) % w) for c in range(w)] for r in range(h)]
    else:
        keys = list(base)
        if not keys:
            return [row[:] for row in grid]
        def color(k):
            q = k % p
            if q in base:
                return base[q]
            return base[min(keys, key=lambda x: min((q-x)%p, (x-q)%p))]
        return [[color(r) for _ in range(w)] for r in range(h)]
